import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def split_physical_rows(all_lines: List[str]) -> List[str]:
        rows = []
        buf = []
        in_quotes = False
        for line in all_lines:
            if not buf and line == "":
                rows.append("")
                continue
            if buf:
                buf.append(line)
            else:
                buf = [line]
            i = 0
            while i < len(line):
                ch = line[i]
                if ch == '"':
                    if in_quotes:
                        if i + 1 < len(line) and line[i + 1] == '"':
                            i += 1
                        else:
                            in_quotes = False
                    else:
                        in_quotes = True
                i += 1
            if not in_quotes:
                rows.append("\n".join(buf))
                buf = []
        if buf:
            rows.append("\n".join(buf))
        return rows

    logical_rows = split_physical_rows(lines)

    def parse_row(row: str) -> List[str]:
        if row == "":
            return []
        reader = csv.reader(io.StringIO(row), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        try:
            return next(reader)
        except StopIteration:
            return []

    parsed_rows = [parse_row(r) for r in logical_rows if r is not None]

    nonempty = [r for r in parsed_rows if r]
    header_idx = None
    for i, row in enumerate(nonempty):
        upper = [c.strip() for c in row]
        if len(upper) >= 8 and any(re.fullmatch(r"[A-Z][A-Z0-9_ ]*", c) for c in upper):
            if "DATE" in upper and "TIME" in upper:
                header_idx = i
                break
    if header_idx is None:
        for i, row in enumerate(nonempty):
            if len(row) >= 8 and row[:2] == ["DATE", "TIME"]:
                header_idx = i
                break

    data_rows = []
    columns = None

    if header_idx is not None:
        header_row = nonempty[header_idx]
        if header_idx > 0:
            prev = nonempty[header_idx - 1]
            if len(prev) == len(header_row):
                merged = []
                for a, b in zip(prev, header_row):
                    a = a.strip()
                    b = b.strip()
                    merged.append((a + " " + b).strip() if a and b else (a or b))
                columns = merged
            else:
                columns = header_row
        else:
            columns = header_row
        for row in nonempty[header_idx + 1:]:
            data_rows.append(row)
        for row in parsed_rows:
            if not row:
                continue
            if row == header_row:
                continue
            if row in data_rows:
                continue
    else:
        data_rows = nonempty
        if data_rows:
            columns = [f"column_{i+1}" for i in range(max(len(r) for r in data_rows))]
        else:
            columns = []

    width = len(columns) if columns else 0
    normalized_rows = []
    for row in data_rows:
        if width and len(row) != width:
            if len(row) < width:
                row = row + [""] * (width - len(row))
            else:
                row = row[:width]
        normalized_rows.append([str(v) for v in row])

    return {"columns": [str(c) for c in columns], "rows": normalized_rows}
